<script setup>
import {ref,onMounted} from 'vue'
import {adminFetch} from './adminApi.js'
const props=defineProps({selectable:Boolean})
const emit=defineEmits(['select'])
const items=ref([]),total=ref(0),page=ref(1),search=ref(''),loading=ref(false),busy=ref(false),error=ref('')
const types={product:'Товар',page:'Страница',post:'Статья',settings:'Настройки'}
const size=value=>Number(value)>=1048576?(Number(value)/1048576).toFixed(1)+' МБ':Math.ceil(Number(value)/1024)+' КБ'
async function load(number=page.value){if(loading.value)return;page.value=number;loading.value=true;error.value='';try{const response=await adminFetch('/api/admin/media?'+new URLSearchParams({q:search.value,page:String(number)}));const result=await response.json();if(!response.ok)throw Error(result.error||'Ошибка загрузки');items.value=result.items;total.value=result.total;if(!items.value.length&&number>1){page.value=number-1;loading.value=false;return load(number-1)}}catch(e){error.value=e.message}finally{loading.value=false}}
async function upload(event){const file=event.target.files?.[0];if(!file)return;busy.value=true;error.value='';try{const body=new FormData();body.append('file',file);const response=await adminFetch('/api/uploads',{method:'POST',body});const result=await response.json();if(!response.ok)throw Error(result.error||'Ошибка загрузки');search.value='';await load(1)}catch(e){error.value=e.message}finally{busy.value=false;event.target.value=''}}
async function remove(item){if(!confirm('Удалить файл «'+item.original_name+'»? Это действие нельзя отменить.'))return;busy.value=true;error.value='';try{const response=await adminFetch('/api/admin/media/'+item.url.split('/').pop(),{method:'DELETE'});if(!response.ok){const result=await response.json();if(result.usage)item.usage=result.usage;throw Error(result.error||'Ошибка удаления')}await load()}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(()=>load())
</script>
<template>
<section class="media-library"><div class="media-toolbar"><form @submit.prevent="load(1)"><input v-model="search" maxlength="200" placeholder="Имя файла или адрес" aria-label="Поиск файлов"><button type="submit" class="row-btn" :disabled="loading||busy">Найти</button></form><label class="upload-label">Загрузить изображение<input type="file" accept="image/jpeg,image/png,image/webp" :disabled="busy||loading" @change="upload"></label></div><p>JPG, PNG, WebP до 5 МБ. Использование учитывается после сохранения содержимого, включая черновики.</p><p v-if="error" class="alert" role="alert">{{error}}</p><p v-if="loading||busy" role="status">Подождите…</p><p>Файлов: {{total}}</p><div class="media-grid"><article v-for="item in items" :key="item.url" class="media-card"><img :src="item.url" :alt="item.original_name" loading="lazy"><strong>{{item.original_name}}</strong><small>{{size(item.size)}} · {{item.mime}}</small><details v-if="item.usage.length"><summary>Используется: {{item.usage.length}}</summary><ul><li v-for="use in item.usage" :key="use.type+use.id">{{types[use.type]}}: {{use.title}}</li></ul></details><small v-else>Пока не используется</small><div class="media-actions"><button v-if="selectable" type="button" class="primary-btn" :disabled="busy||loading" @click="emit('select',item.url)">Выбрать</button><button v-else type="button" class="row-btn danger" :disabled="busy||loading||item.usage.length>0" @click="remove(item)">Удалить</button></div></article></div><p v-if="!loading&&!items.length">Файлы не найдены.</p><nav class="media-pagination" aria-label="Страницы медиатеки"><button type="button" class="row-btn" :disabled="page<=1||busy||loading" @click="load(page-1)">← Назад</button><span>{{page}} / {{Math.max(1,Math.ceil(total/24))}}</span><button type="button" class="row-btn" :disabled="page*24>=total||busy||loading" @click="load(page+1)">Далее →</button></nav></section>
</template>
<style scoped>
.media-toolbar{display:flex;flex-wrap:wrap;align-items:center;gap:20px;}form{display:flex;flex-wrap:wrap;gap:8px;}input{max-width:100%;min-width:0;padding:10px;border:1px solid #d6e2da;border-radius:8px;}.upload-label{display:grid;gap:8px;font-size:13px;}.media-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(220px,100%),1fr));gap:18px;}.media-card{min-width:0;padding:16px;border:1px solid #dce6df;border-radius:12px;display:flex;flex-direction:column;gap:12px;background:white;}.media-card img{width:100%;height:150px;object-fit:contain;background:#f5f7f5;border-radius:8px;}.media-card strong,li{overflow-wrap:anywhere;}.media-card small,p{font-size:12px;color:#61756a;}.media-actions{margin-top:auto;}.media-pagination{display:flex;align-items:center;justify-content:center;gap:12px;margin-top:24px;}details{font-size:12px;}ul{padding-left:18px;}
</style>
